INSERT INTO build_status VALUES ('R178','experiment/drnas-r178-mixed-spectrum100-20261106','FROZEN_SHA100_NATIVE_SELFTEST_PASS_SHARDS_RUNNING','https://github.com/Frane12/AndroidGameTest/actions/runs/42189798453','4 known real original mixed SHA sources + 96 deterministic planted SAT mixed XOR/AND/OR, 100 distinct SHA checked. Pinned binary/CaDiCaL2.1 and native resolution selftest pass. 10 shards x 10 formulas x 2 reps x 4 arms = 800 paired trials; 30s generated /45s original caps. Not blind; original cases previously seen. Baseline-calibrated 0.1-30s strata are outcomes not quotas; no result before audit.') ON CONFLICT(version) DO UPDATE SET branch=excluded.branch,status=excluded.status,last_evidence_url=excluded.last_evidence_url,notes=excluded.notes;
INSERT INTO benchmark_cohorts (cohort_id,version,cohort_type,github_run_id,original_formulas,total_attempts,audit_status,source_url,notes) VALUES ('r178_mixed_spectrum','R178 four-arm mixed SAT spectrum','4_reused_original_and_96_generated_planted_sat',42189798453,100,800,'R178_SPECTRUM_100_AUDIT_PASS_NOT_BLIND','https://github.com/Frane12/AndroidGameTest/actions/runs/42189798453','4 known source SHA mixed original formulas all timeout (8 attempts/arm), 96 generated planted SAT mixed formulas all solved (192 attempts/arm). 2 repeats 4 arms 800 trials. CaDiCaL baseline 92/96 generated formulas <0.1s, 4/96 0.1..1s, 0/96 1..30s. CaDiCaL fastest; neither R177 arm delivered overall speedup. NOT BLIND, generated not external; UNSAT independent LRAT unavailable.') ON CONFLICT(cohort_id) DO UPDATE SET version=excluded.version,cohort_type=excluded.cohort_type,github_run_id=excluded.github_run_id,original_formulas=excluded.original_formulas,total_attempts=excluded.total_attempts,audit_status=excluded.audit_status,source_url=excluded.source_url,notes=excluded.notes;
