-- DRNAS SAT 2026-11-07: verified Ultimate R1/R2/R2 budget benchmark history and theory findings.
-- Previous 2026-11-06 history is preserved verbatim. These additions are idempotent; provisional R2x is a build status only.
PRAGMA foreign_keys=ON;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS benchmark_mode_telemetry (cohort_id TEXT NOT NULL REFERENCES benchmark_cohorts(cohort_id), scope TEXT NOT NULL, mode TEXT NOT NULL, trials INTEGER NOT NULL, solved INTEGER NOT NULL, sat INTEGER, unsat INTEGER, par2_s REAL NOT NULL, live_selected INTEGER, live_activated INTEGER, derived_rows INTEGER, delivered_reasons INTEGER, native_result_missing INTEGER, PRIMARY KEY(cohort_id,scope,mode), CHECK (solved<=trials), CHECK(par2_s>=0));
CREATE TABLE IF NOT EXISTS benchmark_paired_comparisons (cohort_id TEXT NOT NULL REFERENCES benchmark_cohorts(cohort_id), candidate TEXT NOT NULL, reference TEXT NOT NULL, paired_wins INTEGER NOT NULL, paired_losses INTEGER NOT NULL, paired_ties INTEGER NOT NULL, total_par2_gain_s REAL NOT NULL, note TEXT NOT NULL, PRIMARY KEY(cohort_id,candidate,reference));
CREATE TABLE IF NOT EXISTS research_findings (finding_id TEXT PRIMARY KEY, evidence_level TEXT NOT NULL CHECK(evidence_level IN ('AUDIT_CONFIRMED','AUDIT_LIMITED','HYPOTHESIS','IN_PROGRESS')), claim TEXT NOT NULL, supporting_cohort_id TEXT REFERENCES benchmark_cohorts(cohort_id), evidence_url TEXT NOT NULL, caveat TEXT NOT NULL, proposed_test TEXT);
COMMIT;
-- Query cross-build PAR2 only when the exact source manifest, cohort, caps and runner CPU match. Prefer same-run paired comparison.
